package xyz.jovanstoiljkovic.isa.dtos.tag;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.models.Tag;public class TagDTO extends BaseDTO<Tag> {    private Long id;    private String name;    public TagDTO() {    }    public TagDTO(Long id, String name) {        this.id = id;        this.name = name;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }}